function cCard(){const u=S.user,ti=tierIdx(),nx=nextTier(),p=tierProg(),g=goalReward();
  return cTop('บัตรสมาชิก')+`<div class="bd"><div class="mcard im-cans" style="min-height:196px;background-size:cover;background-position:center 30%;box-shadow:inset 0 0 0 999px rgba(11,11,20,.62),0 10px 30px rgba(29,57,208,.35)">${bolt('bg')}<div class="sp" style="position:relative;padding-right:92px"><span>คุณ${esc(u.name)}</span>${lvChip(TIER[ti].k)}</div><div style="position:relative;margin:6px 0 4px"><span class="num" style="font-size:48px;line-height:1" id="cardpts">${fmt(u.pts)}</span> <span class="mut">แต้ม</span></div>${u.pend?`<div class="mut" style="font-size:12px;position:relative">รอปลดล็อก/พักตรวจ ${fmt(u.pend)} แต้ม</div>`:''}<div class="mut" style="font-size:11px;position:relative">แต้มหมดอายุแบบ rolling 12 เดือน</div><div class="mut" style="font-size:12px;margin-top:8px;position:relative;max-width:150px">${nx?`ชาร์จ ${weeksIn()}/${nx.w} สัปดาห์ ใน 8 สัปดาห์ล่าสุด เพื่อขึ้น ${nx.k}`:'ชาร์จเต็มทุกระดับแล้ว'}</div><span style="position:absolute;right:16px;top:40px;display:flex;flex-direction:column;align-items:center;gap:4px" id="cardbolt">${VoltFX.bolt(p,{size:'lg',flavor:u.flav||'y',label:Math.round(p*100)+'%'})}<small style="font:700 10px 'Bai Jamjuree';letter-spacing:.08em;color:#FFEB00">CHARGE</small></span></div>
  ${g?`<button class="card sp" data-a="c" data-v="goal" style="padding:10px 12px;text-align:left"><span style="font-size:13px"><b>เป้าหมาย</b> · ${esc(g.n)}<br><span class="mut">${g.pts>u.pts?'อีก '+fmt(g.pts-u.pts)+' แต้ม':'แต้มพอแลกแล้ว'}</span></span>${VoltFX.bolt(goalProg(),{size:'md',flavor:'y'})}</button>`:''}
  <div class="qr">${qrSvg(qrSeed)}</div><div style="text-align:center;font-size:13px">แสดง QR นี้เพื่อยืนยันตัวตน · QR ใหม่ใน <b class="num" id="qrt" style="color:var(--yel)">0:${String(qrLeft).padStart(2,'0')}</b></div>
  <div class="ai"><b>QR สมาชิก</b> · ใช้ยืนยันตัวตนที่อีเวนต์และจุดรับของรางวัล (เปลี่ยนทุก 60 วิ)${OPT.b2b?' · ชาร์จจากร้านโชห่วยให้สแกน QR ที่ร้านในเมนู “ชาร์จแต้ม”':''}</div>
  <div style="margin-top:auto;display:grid;grid-template-columns:1fr 1fr 1.2fr;gap:8px"><button class="btn bo" style="font-size:14px" data-a="c" data-v="collect">ใบเสร็จ</button><button class="btn bo" style="font-size:14px" data-a="collectTab" data-v="${OPT.b2b?'shop':'code'}">${OPT.b2b?'สแกนร้าน':'รหัสใต้ห่วง'}</button><button class="btn by" style="font-size:14px" data-a="c" data-v="rewards">แลกรางวัล</button></div></div>`}

function cCollect(){const u=S.user,ui=S.ui,t=!OPT.b2b&&ui.tab==='shop'?'code':ui.tab,mine=S.receipts.filter(r=>r.me).slice().reverse();
  let h=cTop('ชาร์จแต้ม')+`<div class="bd"><div class="seg${OPT.b2b?'':' s3'}" role="group" aria-label="ประเภท" style="font-size:12px"><button data-a="collectTab" data-v="code" aria-pressed="${t==='code'}">รหัสใต้ห่วง</button>${OPT.b2b?`<button data-a="collectTab" data-v="shop" aria-pressed="${t==='shop'}">QR ร้าน</button>`:''}<button data-a="collectTab" data-v="receipt" aria-pressed="${t==='receipt'}">ใบเสร็จ</button><button data-a="collectTab" data-v="online" aria-pressed="${t==='online'}">ออนไลน์</button></div>
  <details class="note"><summary>กติกาการได้แต้ม</summary>190 ml = ${S.rules.p190} · 310 ml = ${S.rules.p310} แต้ม · ชาร์จได้ ≤ ${S.rules.capCans} กระป๋อง/วัน (วันนี้ ${u.cansToday}/${S.rules.capCans}) · <b>Retail Boost +${S.rules.bonus7}</b> เมื่อรหัส 310 ml ตรงกับใบเสร็จ 7-Eleven${u.boostPool?` · <span class="ok">พร้อมรับ Boost ${u.boostPool} กป.</span>`:''}</details>`;
  if(t==='code')h+=`<label class="f"><span>รหัสใต้ห่วง (ช่องทางหลัก)</span><input class="in" id="ccode" placeholder="VOLT-XXXX-XXXX" autocomplete="off" ${u.codeFails>=5?'disabled':''}></label><span class="mut" style="font-size:12px">รหัสทดลอง: VOLT-7K2P-9QX4 (310) · VOLT-A1B2-C3D4 (190) · ใช้ได้ครั้งเดียว · ผิด 5 ครั้งล็อก 15 นาที</span>${u.codeFails?`<span class="${u.codeFails>=5?'bad':'warn'}" style="font-size:13px">${u.codeFails>=5?'กรอกผิดครบ 5 ครั้ง ล็อก 15 นาที':'กรอกผิด '+u.codeFails+'/5 ครั้ง'}</span>`:''}<button class="btn by" data-a="sendCode" ${u.codeFails>=5?'disabled':''}>ยืนยันรหัส</button>`;
  else if(t==='shop'){const sc=ui.sc;
    if(!sc)h+=`<span class="h3">สแกน QR ที่ร้านโชห่วย (กระป๋อง 190 ml)</span><span class="mut" style="font-size:12.5px">สแกน QR ที่ตั้งไว้ที่ร้าน แล้วเลือกจำนวนกระป๋อง ร้านกดอนุมัติ แต้มจึงเข้า · ระบบตรวจตำแหน่ง GPS ของคุณกับร้าน</span><div class="cam" style="min-height:120px"><i></i><span>เดโม: แตะร้านที่ต้องการสแกน</span></div>${S.shops.filter(x=>!x.sus).slice(0,3).map((x,i)=>`<button class="li" style="text-align:left;width:100%" data-a="scanShop" data-v="${x.id}"><span class="thumb" style="background:#2147FF">${bolt()}</span><div class="t"><b>${esc(x.n)}</b><span class="mut">${esc(x.a)} · ${(0.3+i*0.6).toFixed(1)} กม.${x.risk==='สูง'?' · ร้านถูกเฝ้าระวัง':''}${i===0?' · ร้านบนมือถือฝั่งขวา':''}</span></div><span class="mini">สแกน</span></button>`).join('')}`;
    else{const sh=S.shops.find(x=>x.id===sc.id),cp=cartPts(sc.cart);h+=`<div class="card sp" style="padding:10px 12px"><span><b>${esc(sh.n)}</b><br><small class="mut">สแกน QR ร้านแล้ว</small></span><button class="mini o" data-a="scanReset">เปลี่ยนร้าน</button></div>
      ${['s190','s310'].map(k=>`<div class="card" style="display:flex;flex-direction:column;gap:6px;padding:10px 12px"><div class="sp"><b>กระป๋อง ${SKU[k].s}</b><span class="chip">${S.rules[k==='s190'?'p190':'p310']} แต้ม</span></div>${['y','c','p'].map(f=>`<div class="sp"><span><i class="cthumb im-can-${f}"></i> ${FL[f]}</span><span class="step"><button data-a="cq" data-v="${k}|${f}|-1" aria-label="ลด ${FL[f]}">−</button><b>${sc.cart[k][f]}</b><button data-a="cq" data-v="${k}|${f}|1" aria-label="เพิ่ม ${FL[f]}">+</button></span></div>`).join('')}</div>`).join('')}
      <label class="chk"><input type="checkbox" id="gpsout" ${sc.gpsOut?'checked':''} data-a="gpsToggle"> จำลองตำแหน่งนอกรัศมีร้าน (GPS)</label>
      <div class="sp" style="font-size:15px"><b>รวม ${cp.q} กระป๋อง</b><b class="num" style="font-size:22px">+${cp.p} แต้ม</b></div><button class="btn by" data-a="sendShopReq" ${cp.q?'':'disabled'}>ส่งให้ร้านอนุมัติ</button>`}}
  else if(t==='receipt')h+=`<div class="f"><span>รูปใบเสร็จ (1–6 รูป · ส่งภายใน 7 วัน · เก็บต้นฉบับไว้)</span><div style="display:flex;gap:6px;align-items:center"><span class="step"><button class="bo x" data-a="imgs" data-v="-1" aria-label="ลดรูป">−</button><b class="num" style="width:22px;text-align:center">${ui.rcImgs}</b><button class="bo x" data-a="imgs" data-v="1" aria-label="เพิ่มรูป">+</button></span><span class="mut" style="font-size:12px">รูป · ใบเสร็จยาวถ่ายแยกส่วนได้</span></div></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><label class="f"><span>ร้าน</span><select class="in" id="rstore"><option>7-Eleven</option><option>Lawson</option><option>Villa Market</option><option>Makro</option></select></label><label class="f"><span>เลขใบเสร็จ</span><input class="in" id="rno" value="R-${Math.floor(1000+Math.random()*8999)}-${Math.floor(10000+Math.random()*89999)}"></label>
    <label class="f"><span>สินค้า</span><select class="in" id="rsku"><option value="s310">310 ml</option><option value="s190">190 ml</option></select></label><label class="f"><span>จำนวน</span><input class="in" id="rqty" type="number" min="1" max="24" value="2"></label></div>
    <div class="f"><span>รส</span><div style="display:flex;gap:6px;flex-wrap:wrap">${Object.keys(FL).map(k=>`<button class="chip" data-a="fl" data-v="${k}" aria-pressed="${ui.fl===k}"><i class="cthumb im-can-${k}"></i>${FL[k]}</button>`).join('')}</div></div>
    <label class="chk"><input type="checkbox" id="rblur"> จำลองรูปเบลอ (ระบบส่งคนตรวจ)</label><label class="chk"><input type="checkbox" id="raig"> จำลองใบเสร็จที่ AI สร้าง (ระบบตรวจพบ)</label>
    <div class="ai" style="display:flex;gap:10px;align-items:center"><span class="im-bm-y" style="width:40px;height:40px;border-radius:50%;background-size:cover;flex:none"></span><span style="flex:1"><b>ผู้ช่วยในหน้านี้</b> · ตรวจรูปและบอกแต้มก่อนกดส่ง</span><button class="mini" data-a="assist">ตรวจ</button></div>
    <span class="mut" style="font-size:12px">ลองส่งเลขซ้ำ <b>S-1123-88001</b> เพื่อดูระบบจับใบเสร็จซ้ำ</span><button class="btn by" data-a="sendReceipt">ส่งใบเสร็จ</button>`;
  else h+=`<label class="f"><span>ร้านค้าออนไลน์</span><select class="in" id="oplat"><option value="off">Volt Official Store (Shopee)</option><option value="off2">Volt Official Store (Lazada)</option><option value="tt">Volt Official Store (TikTok Shop)</option><option value="other">ร้านอื่นใน Shopee / Lazada</option></select></label><label class="f"><span>เลขออเดอร์</span><input class="in" id="ono" value="2401${Math.floor(100000+Math.random()*899999)}"></label><label class="f"><span>แพ็ก</span><select class="in" id="osku"><option value="6">310 ml แพ็ก 6</option><option value="12">310 ml แพ็ก 12</option></select></label><span class="mut" style="font-size:12px">แนบเลขออเดอร์และรูป · แต้มพัก ${S.rules.holdDays} วันจนปิดช่วงคืนสินค้า · ร้านอื่นส่งทีมตรวจ</span><button class="btn by" data-a="sendOnline">ผูกออเดอร์</button>`;
  h+=`<span class="h3" style="margin-top:4px">สถานะล่าสุด</span>`+(mine.map(r=>`<div class="li"><div class="t"><b>${esc(r.store)}</b><span class="mut">${SKU[r.sku]?SKU[r.sku].s:esc(r.sku)} × ${r.qty} · ${esc(r.no)}</span></div><b class="${r.st==='ok'?'ok':r.st==='review'||r.st==='checking'?'warn':'bad'}">${r.st==='ok'?'+'+r.pts+' แต้ม':r.st==='held'?'พักตรวจ '+r.pts:r.st==='checking'?'ระบบกำลังตรวจ…':r.st==='review'?'ทีมตรวจ ≤24 ชม.':r.st==='resubmit'?'ขอรูปใหม่':r.st==='dup'?'ใบเสร็จซ้ำ':'ไม่ผ่าน'}${r.st==='no'&&!r.appealed?` <button class="mini o" data-a="appealReq" data-v="${r.id}">อุทธรณ์</button>`:''}</b></div>`).join('')||'<div class="mut" style="font-size:13px">ยังไม่มีรายการ</div>')+`</div>`;
  return h}

function rwItem(r){const u=S.user,lk=!allowed(r)?`อายุ ${r.minAge}+`:soldOut(r)?'หมดแล้ว':r.tier==='D'&&tierIdx()<2?'ปลดล็อก LF3':'';
  const price=r.k==='perk'?'สิทธิ์พาร์ทเนอร์ · ฟรี':`${fmt(r.pts)} แต้ม${r.ship?' · จัดส่ง':''}${left(r)<20&&r.k!=='perk'?` · เหลือ ${left(r)}`:''}`;
  const g=goalReward()&&goalReward().id===r.id;
  return `<div class="li">${rwThumb(r)}<div class="t"><b>${esc(r.n)}</b><span class="mut">${price}${r.note?' · '+r.note:''}</span></div>${lk?`<span class="lock">🔒 ${lk}</span>`:`<span style="display:flex;gap:4px"><button class="mini o" data-a="heart" data-v="${r.id}" aria-label="ถูกใจ" aria-pressed="${u.hearts.includes(r.id)}">${u.hearts.includes(r.id)?'♥':'♡'}</button>${r.k==='perk'?'':`<button class="mini o" data-a="goal" data-v="${r.id}" aria-pressed="${g}">${g?'เป้า ✓':'ตั้งเป้า'}</button>`}<button class="mini" data-a="openRw" data-v="${r.id}">${r.k==='perk'?'รับ':'แลก'}</button></span>`}</div>`}
function cRewards(){const u=S.user,ui=S.ui,ti=tierIdx(),g=goalReward(),f=ui.rg;
  const rec=recommend(),nb=nextAction();
  const cat=S.rewards.filter(r=>f==='all'||(f==='merch'?r.k==='merch':f==='perk'?r.k==='perk':r.gs.includes(f)));
  return cTop('แลกรางวัล')+`<div class="bd" style="gap:10px"><div class="ai"><b>ขั้นต่อไป</b> · ${esc(nb.t)}${u.pers&&u.groups.length?'':' <small class="mut">(ปิดการแนะนำเฉพาะตัวอยู่ แสดงยอดนิยมรวม)</small>'}</div>
  ${g?`<button class="card sp" data-a="c" data-v="goal" style="padding:10px 12px;text-align:left"><span style="font-size:13px"><b>เป้าหมายของฉัน</b><br>${esc(g.n)} · ${g.pts>u.pts?'อีก '+fmt(g.pts-u.pts)+' แต้ม':'แลกได้แล้ว'}</span>${VoltFX.bolt(goalProg(),{size:'md',flavor:'y'})}</button>`:''}
  <div class="sp"><span class="h3">แนะนำสำหรับคุณ</span><span class="mut" style="font-size:11.5px">${rec.length} รายการ</span></div>${rec.slice(0,3).map(x=>`<div class="li">${rwThumb(x.r)}<div class="t"><b>${esc(x.r.n)}</b><span class="mut">${fmt(x.r.pts)} แต้ม</span><span class="why">เพราะ${esc(x.why)}</span></div><button class="mini" data-a="openRw" data-v="${x.r.id}">แลก</button></div>`).join('')}
  <div class="chips">${[['all','ทั้งหมด'],...VOLT.lifestyles.map(l=>[l.id,l.th]),['merch','Merch'],['perk','พาร์ทเนอร์']].map(([k,l])=>`<button class="chip" data-a="rg2" data-v="${k}" aria-pressed="${f===k}">${l}</button>`).join('')}</div>${cat.slice(0,14).map(rwItem).join('')}<span class="mut" style="font-size:11.5px">แสดง ${Math.min(14,cat.length)} จาก ${cat.length} รายการ · รางวัลส่งจริง: ลูกค้าเป็นผู้รับภาระภาษีหัก ณ ที่จ่ายตามกฎหมาย (ถ้ามี)</span></div>`}
function cGoal(){const g=goalReward(),u=S.user;if(!g)return cRewards();const p=goalProg(),eta=Math.max(0,Math.ceil((g.pts-u.pts)/S.rules.p310));
  return cTop('เป้าหมายของฉัน','rewards')+`<div class="bd center" style="align-items:center;gap:12px"><b class="h3" style="font-size:20px">${esc(g.n)}</b><div id="goalbolt">${VoltFX.bolt(p,{size:'xl',flavor:'y',label:Math.round(p*100)+'%'})}</div><span>${p>=1?'แต้มพอแล้ว แลกได้เลย':`อีก <b class="num" style="color:var(--yel);font-size:22px">${fmt(g.pts-u.pts)}</b> แต้ม · ประมาณ ${eta} กระป๋อง 310 ml`}</span><div class="ai" style="width:100%;text-align:left"><b>AI NOTI</b> · ทุกครั้งที่ชาร์จ โบลต์จะเติมขึ้นและแจ้งว่าเหลืออีกกี่แต้ม</div><button class="btn by" style="width:100%" data-a="openRw" data-v="${g.id}">แลกเลย</button><button class="btn bo" style="width:100%" data-a="goalClear">เอาเป้าหมายออก</button></div>`}

function cRedeem(){const d=S.ui.rd,u=S.user;if(!d)return cRewards();const r=S.rewards.find(x=>x.id===d.id);let b='';
  const head=`<div style="height:120px;border-radius:20px;background:radial-gradient(80% 90% at 50% 30%,#2A3590,#0B0B14);display:grid;place-items:center;flex:none;font:italic 900 34px 'Bai Jamjuree'">${r.k==='merch'?'👕':r.k==='perk'?'🤝':'🎁'}</div><b class="h3" style="font-size:19px">${esc(r.n)}</b>`;
  if(d.step==='done')b=`<div class="center" style="display:flex;flex-direction:column;gap:12px;padding-top:20px;align-items:center"><div id="dnbolt">${VoltFX.bolt(1,{size:'xl',flavor:'y'})}</div><b class="big">สำเร็จ!</b><span>${esc(d.msg)}</span>${d.code?`<div class="card num" style="font-size:22px;letter-spacing:.08em;color:var(--yel)">${d.code}</div>`:''}<span class="mut">คงเหลือ ${fmt(u.pts)} แต้ม · แจ้งใน LINE แล้ว</span><button class="btn by" data-a="c" data-v="rewards" style="width:100%">กลับหน้ารางวัล</button></div>`;
  else if(d.step==='otp')b=head+`<span>ยืนยันเบอร์โทรด้วย OTP (ครั้งแรกที่แลก)</span><label class="f"><span>รหัส OTP 6 หลัก ส่งไปที่ 08x-xxx-4521</span><input class="in" id="otp" inputmode="numeric" maxlength="6" placeholder="ใส่เลขอะไรก็ได้ 6 หลัก"></label><button class="btn by" data-a="otp">ยืนยัน OTP</button>`;
  else if(d.step==='addr')b=head+`<span class="h3">ที่อยู่จัดส่ง</span><label class="f"><span>ชื่อผู้รับ</span><input class="in" id="ad1" value="คุณ${esc(u.name)}"></label><label class="f"><span>ที่อยู่</span><input class="in" id="ad2" value="99/1 ถ.พหลโยธิน แขวงสามเสนใน กรุงเทพฯ 10400"></label><span class="mut" style="font-size:12px">ของรางวัลส่งภายใน 7–14 วัน · ที่อยู่ใช้เพื่อจัดส่งเท่านั้น</span><button class="btn by" data-a="addr">ยืนยันที่อยู่</button>`;
  else{const can=r.pts<=u.pts,why=!allowed(r)?`รางวัลนี้สำหรับอายุ ${r.minAge} ปีขึ้นไป`:soldOut(r)?'รางวัลหมดแล้ว':!can?`แต้มไม่พอ (ขาดอีก ${fmt(r.pts-u.pts)})`:'';
    b=head+`<span class="mut" style="font-size:12.5px">${r.ship?'จัดส่งถึงบ้านทั่วประเทศ · ':'ส่งโค้ดทาง LINE ทันที · '}จำกัด ${r.cap} สิทธิ์/คน${r.imgExpire?' · ภาพสินค้า Three Man Down ใช้ได้ถึง '+r.imgExpire:''}${r.drop?' · Drop ล็อตแรก 50%':''}</span><div class="sp card"><span>ใช้แต้ม</span><b class="num" style="font-size:24px;color:var(--yel)">${fmt(r.pts)}</b></div><div class="sp"><span>คงเหลือหลังแลก</span><b class="num">${fmt(Math.max(0,u.pts-r.pts))}</b></div>${why?`<span class="bad" style="font-size:13px">${why}</span>`:''}<button class="btn by vhold" style="margin-top:auto" data-hold="confirmRw:" ${why?'disabled':''}>⚡ กดค้างเพื่อแลก</button>`}
  return `<div class="bar"><button class="x" data-a="c" data-v="rewards" aria-label="กลับ">‹</button><b>แลกรางวัล</b><span class="chip y">${fmt(u.pts)}</span></div><div class="bd">${b}</div>`}

function cTier(){const u=S.user,ti=tierIdx(),nx=nextTier(),p=tierProg(),isH=S.ui.c==='hist';
  const miss=[{id:'quizP',n:`Charge Profile ${u.profileQ}/10`,p:30,done:u.profilePaid,go:'quizP'},{id:'quizW',n:'Weekly Quiz 3 ข้อ',p:5,done:u.weeklyDone,go:'quizW'},{id:'trio',n:`Flavor Trio ${['y','c','p'].filter(k=>u.cans30[k]>0).length}/3 รส`,p:10,done:u.trioDone,go:'collect'},{id:'ref',n:'ชวนเพื่อนสมัคร',p:5,done:false,go:'invite'}];
  return cTop(isH?'ประวัติแต้ม':'Tier ของฉัน')+`<div class="bd" style="gap:10px"><div class="card sp" style="padding:12px 14px;gap:14px;flex:none"><span id="tierbolt">${VoltFX.bolt(p,{size:'lg',flavor:u.flav||'y',label:Math.round(p*100)+'%'})}</span><div style="flex:1;display:flex;flex-direction:column;gap:8px;min-width:0"><b class="h3">Charge Streak · 8 สัปดาห์ล่าสุด</b><div class="vstreak" style="grid-template-columns:repeat(8,minmax(0,1fr))">${u.wk.map((x,i)=>`<span class="${x?'on':''} ${i===7&&!u.week?'now':''}">${i+1}</span>`).join('')}</div><span class="mut" style="font-size:12px">${nx?`${nx.k}: ${nx.d} · ตอนนี้ ${weeksIn()}/${nx.w}`:'ชาร์จครบ 8 สัปดาห์แล้ว'} · สัปดาห์นี้${u.week?'ชาร์จแล้ว ✓':'ยังไม่ได้ชาร์จ'}</span></div></div>
  <div class="tiers">${TIER.map((t,k)=>`<span class="${k<ti?'done':k===ti?'on':''}">${t.k}</span>`).join('')}</div>
  <span class="h3">ภารกิจ</span>${miss.map(m=>`<div class="li"><span class="tick ${m.done?'on':''}">${m.done?'✓':''}</span><span class="t">${m.n}</span>${m.done?`<b class="num" style="color:var(--yel)">+${m.p}</b>`:`<button class="mini" data-a="${m.go==='invite'?'invite':'c'}" data-v="${m.go}">ทำ +${m.p}</button>`}</div>`).join('')}
  <div class="sp"><span class="h3">ประวัติแต้ม</span>${u.pend?`<span class="chip" style="font-size:11px">รอปลดล็อก ${fmt(u.pend)}</span>`:''}</div><div class="hist">${(S.hist||[]).slice(0,isH?20:8).map(x=>`<div><span>${esc(x.l)}</span><b class="${x.p>=0?'ok':'bad'}">${x.p>=0?'+':''}${fmt(x.p)}</b></div>`).join('')||'<div><span class="mut">ยังไม่มีรายการ</span></div>'}${u.pendList.map(x=>`<div><span>${esc(x.l)} <small class="mut">(${x.firstCan?'รอชาร์จกระป๋องแรก':'พักตรวจ '+x.hold+' วัน'})</small></span><b class="warn">+${x.p}</b></div>`).join('')}</div>
  <div class="card sp" style="padding:10px 12px"><span style="font-size:13px"><b>Community</b> · อันดับสัปดาห์นี้ <b class="num" style="color:var(--yel)">#${(lbRows('wk').find(x=>x.me)||{rank:'-'}).rank}</b></span><button class="mini" data-a="c" data-v="board">ดูอันดับ</button></div></div>`}

function cNear(){const sh=S.shops.concat(S.newShops);
  return cTop(OPT.b2b?'ร้านสะสมแต้มใกล้ฉัน':'ร้านที่มี Volt ใกล้ฉัน','profile')+`<div class="bd"><div class="nmap">${sh.map((s,i)=>`<span style="position:absolute;left:${18+i*18}%;top:${25+(i%2)*35}%;width:16px;height:16px;border-radius:50%;background:${s.sus?'#666':'var(--yel)'};box-shadow:0 0 12px var(--yel)"></span>`).join('')}<span style="position:absolute;left:45%;top:50%;width:14px;height:14px;border-radius:50%;background:var(--cyan);border:3px solid #fff"></span></div>`+
  sh.map((s,i)=>`<div class="li"><span class="thumb" style="background:#2147FF">${bolt()}</span><div class="t"><b>${esc(s.n)}</b><span class="mut">${esc(s.a)} · ${(0.3+i*0.6).toFixed(1)} กม.</span></div>${s.sus?'<span class="lock">ปิดชั่วคราว</span>':`<span class="chip">${OPT.b2b?'สแกนได้':'มีขาย'}</span>`}</div>`).join('')+`</div>`}

/* ----- quizzes: Charge Profile (10) / Weekly (3). Handoff gives question text only; options are prototype assumptions ----- */
const POPT=[['ก่อน 2540','2540–2549','2550–2557','2558 ขึ้นไป'],['กรุงเทพฯ/ปริมณฑล','ภาคกลาง','ภาคเหนือ/อีสาน','ภาคใต้/ตะวันออก'],['นักเรียน/นักศึกษา','พนักงานบริษัท','ฟรีแลนซ์/ธุรกิจส่วนตัว','อื่น ๆ'],['ดนตรี','เกม','กีฬา','อาหาร'],['เช้า','บ่าย','เย็น','ดึก'],['ทุกวัน','2–3 ครั้ง/สัปดาห์','สัปดาห์ละครั้ง','นาน ๆ ครั้ง'],['1 กระป๋อง','2–3 กระป๋อง','ยกแพ็ก','แล้วแต่โปร'],['7-Eleven','ร้านโชห่วย','Lawson/Makro','ออนไลน์'],['Tropical','Blueberry','Forest Fruit','ชอบทุกรส'],['กาแฟ','ชา/นมเปรี้ยว','เครื่องดื่มชูกำลังเจ้าอื่น','น้ำเปล่า']];
const WOPT=['ตัวเลือก A (ตัวอย่าง)','ตัวเลือก B (ตัวอย่าง)','ตัวเลือก C (ตัวอย่าง)'];
function curQ(){const u=S.user,ui=S.ui;if(ui.c==='quizP'){const i=Math.min(9,u.profileQ);return{q:S.profileQs[i].q,why:S.profileQs[i].why,opts:POPT[i]}}
  const wk=S.weekly[ui.wq%S.weekly.length];return{q:wk.qs[ui.qi]||'—',opts:WOPT,wk}}
function cQuiz(){const u=S.user,ui=S.ui,P=ui.c==='quizP';
  if(P){
    if(u.profileQ>=10)return cTop('Charge Profile','tier')+`<div class="bd center" style="align-items:center;gap:12px;padding-top:30px">${VoltFX.bolt(1,{size:'xl',flavor:'y'})}<b class="big">ครบแล้ว!</b><span>${u.profilePaid?'ได้รับ 30 แต้มแล้ว':'30 แต้มรอปลดล็อกหลังชาร์จกระป๋องแรก'}</span><button class="btn by" style="width:100%" data-a="c" data-v="tier">กลับ</button></div>`;
    const q=curQ();
    return cTop('Charge Profile','tier')+`<div class="bd"><div class="vpbar"><i style="width:${u.profileQ*10}%"></i></div><span class="mut" style="font-size:12px">ข้อ ${u.profileQ+1} จาก 10 · ตอบครบรับ 30 แต้ม${u.firstCan?'':' (ปลดล็อกหลังชาร์จกระป๋องแรก)'}</span><b class="h3" style="font-size:18px">${esc(q.q)}</b><span class="mut" style="font-size:12px">เพื่อ: ${esc(q.why)}</span>${q.opts.map((o,i)=>`<button class="btn bo" style="font-size:15px;justify-content:flex-start;text-align:left" data-a="qP" data-v="${i}">${esc(o)}</button>`).join('')}<span class="mut" style="font-size:11.5px">ใช้ข้อมูลเพื่อแนะนำรางวัลที่ตรงใจ ปิดได้ที่การตั้งค่าความเป็นส่วนตัว</span></div>`}
  const q=curQ(),wk=q.wk,nochg=u.lastDays>=14;
  if(u.weeklyDone)return cTop('Weekly Quiz','tier')+`<div class="bd center" style="align-items:center;gap:12px;padding-top:30px">${VoltFX.bolt(1,{size:'xl',flavor:'c'})}<b class="big">สัปดาห์นี้ตอบแล้ว</b><span class="mut">ธีมสัปดาห์หน้า: ${esc(S.weekly[(ui.wq+1)%S.weekly.length].theme)}</span><button class="btn by" style="width:100%" data-a="c" data-v="tier">กลับ</button></div>`;
  return cTop('Weekly Quiz','tier')+`<div class="bd"><div class="vpbar"><i style="width:${(ui.qi/3)*100}%"></i></div><span class="mut" style="font-size:12px">สัปดาห์ที่ ${(ui.wq%S.weekly.length)+1} · ธีม ${esc(wk.theme)} · ข้อ ${ui.qi+1}/3 · ${nochg?'ไม่ได้ชาร์จเกิน 14 วัน จึงได้ 1 สิทธิ์จับรางวัลแทน 5 แต้ม':'ตอบครบรับ 5 แต้ม'}</span><b class="h3" style="font-size:18px">${esc(q.q)}</b>${q.opts.map((o,i)=>`<button class="btn bo" style="font-size:15px;justify-content:flex-start;text-align:left" data-a="qW" data-v="${i}">${esc(o)}</button>`).join('')}</div>`}

/* ----- draws / wallet / board / buddy ----- */
function cDraws(){const u=S.user;
  return cTop('Lucky Draw')+`<div class="bd" style="gap:10px"><div class="ai"><b>ลุ้นด้วยแต้ม</b> · ${S.rules.entryCost} แต้ม = 1 สิทธิ์ · เลือกสุ่มจากสิทธิ์ทั้งหมด ผลแสดงที่นี่และทาง LINE · ผู้ชนะตรวจอายุ ${S.rules.ageMin}+ ก่อนส่งรางวัล</div>
  ${S.draws.map(d=>{const mine=u.entries[d.id]||0,lock=d.only7&&!hasBought7()?'ต้องซื้อ 7-Eleven 310 ml พร้อมใบเสร็จก่อน':d.status!=='open'?'ยังไม่เปิดรับ':'';
    return `<div class="card" style="display:flex;flex-direction:column;gap:6px;padding:12px"><div class="sp"><b>${esc(d.n)}</b><span class="chip ${d.status==='open'?'y':''}">${d.status==='open'?'เปิดรับ':'เร็ว ๆ นี้'}</span></div><span class="mut" style="font-size:12.5px">${esc(d.prize)} · ปิดรับ ${esc(d.cut)}</span><div class="sp"><span style="font-size:13px">สิทธิ์ของคุณ <b class="num" style="color:var(--yel)">${mine}</b> / ${fmt(d.entries+mine)}</span>${lock?`<span class="lock">🔒 ${lock}</span>`:`<button class="mini" data-a="entry" data-v="${d.id}" ${u.pts<S.rules.entryCost?'disabled':''}>ใช้ ${S.rules.entryCost} แต้ม</button>`}</div></div>`}).join('')}</div>`}
function cWallet(){return cTop('กระเป๋าคูปอง')+`<div class="bd">${S.wallet.length?S.wallet.map(w=>`<div class="li"><span class="thumb" style="background:#17A866">🎟</span><div class="t"><b>${esc(w.n)}</b><span class="mut num">${esc(w.code)} · ใช้ได้ ${w.exp}</span></div><span class="chip y">${w.st==='ready'?'พร้อมใช้':'ใช้แล้ว'}</span></div>`).join(''):'<div class="empty" style="color:var(--mut);display:flex;flex-direction:column;align-items:center;gap:8px"><span class="im-mc-y" style="width:120px;height:160px;border-radius:16px;background-size:cover"></span>ยังไม่มีคูปอง ชาร์จกระป๋องเพื่อลุ้น Instant Win ทุกครั้ง</div>'}</div>`}
function cBoard(){const t=S.ui.lbT,rows=lbRows(t),T=[['wk','สัปดาห์'],['mo','เดือน'],['prov','จังหวัด'],['chg','Streak'],['campus','มหาวิทยาลัย']];
  return cTop('Leaderboard')+`<div class="bd"><div class="chips">${T.map(([k,l])=>`<button class="chip" data-a="lbT" data-v="${k}" aria-pressed="${t===k}">${l}</button>`).join('')}</div><span class="mut" style="font-size:11.5px">อันดับจากยอดซื้อจริงที่ผ่านตรวจ · แสดงชื่อย่อ ปิดการแสดงตัวได้ในตั้งค่า</span>${rows.slice(0,8).map(x=>`<div class="li" style="${x.me?'border-color:#FFEB00':''}"><b class="num" style="width:26px">${x.rank}</b><div class="t"><b>${esc(x.n)}</b><span class="mut">${t==='campus'?fmt(x.v)+' คน':fmt(x.v)+(t==='chg'?' วัน':' ฿')}</span></div>${x.me?'<span class="chip y">คุณ</span>':''}</div>`).join('')}${rows.findIndex(x=>x.me)>=8?`<div class="li" style="border-color:#FFEB00"><b class="num" style="width:26px">${rows.find(x=>x.me).rank}</b><div class="t"><b>${esc(rows.find(x=>x.me).n)}</b></div></div>`:''}</div>`}
function cBuddy(){return cTop('Volt Buddy','profile')+`<div class="bd"><div class="card" style="display:flex;gap:12px;align-items:center;padding:10px 12px"><span class="im-mc-${S.user.flav||'y'}" style="width:78px;height:104px;border-radius:14px;background-size:cover;background-position:center;flex:none"></span><span style="font-size:13px"><b class="h3">สวัสดี ผม Volt Bolt</b><br><span class="mut">ผู้ช่วยในแชตของคุณ ถามเรื่องแต้ม รางวัล และร้านใกล้ตัวได้</span></span></div><div class="ai"><b>AI ระดับ 1</b> · ตอบเรื่องกติกา แต้ม รางวัล ร้านใกล้คุณ และขั้นต่อไป · ไม่ให้/หักแต้มเอง · ไม่แลกแทนคุณ · ไม่สนับสนุนการดื่มเกินพอดี</div><div class="chips wrap"><button data-a="ask" data-v="pts">แต้มฉันเหลือเท่าไร</button><button data-a="ask" data-v="how">สะสมแต้มยังไง</button><button data-a="ask" data-v="next">ควรทำอะไรต่อ</button><button data-a="ask" data-v="why">ทำไมแนะนำชิ้นนี้</button><button data-a="ask" data-v="human">ติดต่อทีมงาน</button></div><div class="chat bchat">${S.chat.slice(-6).map(bubOf).join('')}</div></div>`}

